"""Week 3e patch (apply AFTER patch_week3d.py). Save in the repo root and run:  python patch_week3e.py
It OVERWRITES these files with tested versions (only run it if you have not edited them yourself):
  src/skillsgap/supply.py
  src/skillsgap/schema.py
  src/skillsgap/quality.py
  tests/test_pipeline.py
Then run:  python -m pytest -q tests     (expect 15 passed)"""
import json
from pathlib import Path

FILES = json.loads('{"src/skillsgap/supply.py": "\\"\\"\\"Supply-side parser: published university graduation lists (PDF) -> programme-level counts.\\n\\nPRIVACY BY DESIGN: graduate names, registration numbers, gender and nationality columns are\\ncounted but NEVER stored. Only (institution, ceremony, award level, programme, count) leaves\\nthis module.\\n\\"\\"\\"\\nimport io\\nimport logging\\nimport re\\n\\nfrom .schema import make_record\\n\\nlog = logging.getLogger(\\"skillsgap.supply\\")\\n\\nAWARD = re.compile(r\\"\\\\b(bachelor|master|doctor|ph\\\\.?d|post\\\\s?graduate|pgd|diploma|certificate)\\\\b\\", re.I)\\nROW = re.compile(r\\"^\\\\s*(\\\\d{1,4})[.)]?\\\\s+[A-Za-z]\\")\\nSERIAL_JUMP = 60   # largest forward gap in serial numbers we still treat as the same list\\n\\n_LEVELS = [(\\"ph\\", \\"PhD\\"), (\\"doctor\\", \\"PhD\\"), (\\"master\\", \\"Masters\\"), (\\"post\\", \\"Postgraduate diploma\\"),\\n           (\\"pgd\\", \\"Postgraduate diploma\\"), (\\"bachelor\\", \\"Bachelors\\"), (\\"diploma\\", \\"Diploma\\"),\\n           (\\"certificate\\", \\"Certificate\\")]\\n\\n_NON_STEM = re.compile(r\\"business|management|administration|secretarial|education|law|arts|social|\\"\\n                       r\\"journalism|communication|theolog|islamic|shari|human resource|procurement|\\"\\n                       r\\"logistics|finance|banking|public policy|governance|accounting|marketing|\\"\\n                       r\\"monitoring|project planning|library\\", re.I)\\n_STEM = re.compile(r\\"computer|information (technology|systems)|software|engineering|statistics|\\"\\n                   r\\"mathematic|physics|chemistry|biolog|agricultur|environmental science|\\"\\n                   r\\"information security|data|\\\\bscience\\\\b\\", re.I)\\n_REVIEW = re.compile(r\\"medicine|surgery|nursing|biomedical|public health|health|pharmac|dental\\", re.I)\\n\\n\\ndef classify_level(heading):\\n    h = heading.lower()\\n    for key, label in _LEVELS:\\n        if re.search(r\\"\\\\b\\" + re.escape(key), h):\\n            return label\\n    return \\"Other\\"\\n\\n\\ndef classify_field(programme):\\n    \\"\\"\\"PROVISIONAL grouping for the NDPIV STEM:humanities comparison. Health programmes are\\n    flagged REVIEW because the supervisor must confirm whether NDPIV counts them as STEM.\\"\\"\\"\\n    if _REVIEW.search(programme):\\n        return \\"REVIEW_HEALTH\\"\\n    if _NON_STEM.search(programme) and not re.search(r\\"computer|information (technology|systems)|engineering\\", programme, re.I):\\n        return \\"NON_STEM\\"\\n    if _STEM.search(programme):\\n        return \\"STEM\\"\\n    return \\"NON_STEM\\"\\n\\n\\ndef extract_pdf_lines(data):\\n    import pdfplumber\\n    lines = []\\n    with pdfplumber.open(io.BytesIO(data)) as pdf:\\n        for page in pdf.pages:\\n            txt = page.extract_text() or \\"\\"\\n            lines.extend(txt.splitlines())\\n    return lines\\n\\n\\ndef count_confidence(count, matched):\\n    \\"\\"\\"How far the serial-based count is from the rows we could actually read.\\"\\"\\"\\n    ratio = count / matched if matched else 99\\n    return \\"high\\" if ratio <= 1.15 else (\\"medium\\" if ratio <= 1.6 else \\"low\\")\\n\\n\\ndef clean_heading(text):\\n    \\"\\"\\"Drop OCR junk at the end of a heading (e.g. \\".\'qt(\'\\" or a stray single lowercase letter).\\"\\"\\"\\n    toks = text.split()\\n    while toks and (not re.fullmatch(r\\"[A-Za-z()&,/-]+\\", toks[-1]) or (len(toks[-1]) == 1 and toks[-1].islower())):\\n        toks.pop()\\n    return \\" \\".join(toks)\\n\\n\\ndef count_programmes(lines):\\n    \\"\\"\\"Walk lines; an award-like heading starts a bucket; numbered rows increment it.\\n    Each bucket is [heading, rows_matched, highest_serial]. The highest serial number is the\\n    better count, because scanned (OCR) lists lose some rows but keep the final serial.\\n    Returns buckets and the number of numbered rows seen before any heading.\\"\\"\\"\\n    buckets, current, orphan_rows = [], None, 0\\n    for line in lines:\\n        s = line.strip()\\n        if not s:\\n            continue\\n        m = ROW.match(s)\\n        if m:\\n            if current is None:\\n                orphan_rows += 1\\n            else:\\n                current[1] += 1\\n                n = int(m.group(1))\\n                # accept a serial only if it moves forward by at most SERIAL_JUMP: ignores stray numbers\\n                # (years, page numbers, phone digits) but tolerates whole pages of unreadable rows\\n                if current[2] < n <= current[2] + SERIAL_JUMP:\\n                    current[2] = n\\n            continue\\n        if AWARD.search(s) and len(s) < 140 and not re.search(r\\"\\\\d{4}\\", s[:4]):\\n            h = clean_heading(s)\\n            if h and (current is None or current[1] > 0 or current[0] != h):\\n                current = [h, 0, 0]\\n                buckets.append(current)\\n    return [tuple(b) for b in buckets], orphan_rows\\n\\n\\ndef parse_graduation_pdf(data, meta, retrieved_at, method=\\"http_get\\"):\\n    lines = extract_pdf_lines(data)\\n    buckets, orphan = count_programmes(lines)\\n    records, failures = [], []\\n    for heading, matched, top in buckets:\\n        if matched == 0:\\n            failures.append({\\"url\\": meta[\\"url\\"], \\"reason\\": f\\"heading_without_numbered_rows: {heading[:60]}\\"})\\n            continue\\n        records.append(make_record(\\n            \\"supply\\", meta[\\"name\\"], meta[\\"url\\"], retrieved_at, method,\\n            id_parts=[meta[\\"url\\"], heading], raw_for_hash=f\\"{heading}|{top}\\", record_url=meta[\\"url\\"],\\n            institution=meta[\\"institution\\"], ceremony=meta[\\"ceremony\\"],\\n            award_level=classify_level(heading), programme=heading, graduate_count=max(top, matched),\\n            count_basis=\\"last_valid_serial_number\\", rows_matched=matched,\\n            count_confidence=count_confidence(max(top, matched), matched),\\n            field_group_provisional=classify_field(heading)))\\n    if orphan:\\n        failures.append({\\"url\\": meta[\\"url\\"], \\"reason\\": f\\"{orphan} numbered rows before any heading\\"})\\n    if not records:\\n        failures.append({\\"url\\": meta[\\"url\\"], \\"reason\\": \\"no_programme_buckets_parsed (list may be unnumbered or scanned: needs OCR or a custom rule)\\"})\\n    return records, failures\\n", "src/skillsgap/schema.py": "\\"\\"\\"Unified record schema (v0.2, revised after Week 3 labelling) and writers.\\n\\nEvery record carries provenance: source, source_url, record_url, retrieved_at,\\nretrieval_method, pipeline_version, raw_hash, plus a stable record_id.\\nNo personal data is stored: graduation lists are reduced to programme-level counts.\\n\\"\\"\\"\\nimport csv\\nimport hashlib\\nimport json\\nimport re\\nfrom datetime import datetime, timedelta, timezone\\n\\nfrom . import __version__\\n\\nPROVENANCE = [\\"record_id\\", \\"record_type\\", \\"source\\", \\"source_url\\", \\"record_url\\",\\n              \\"retrieved_at\\", \\"retrieval_method\\", \\"pipeline_version\\", \\"raw_hash\\"]\\nDEMAND = [\\"title\\", \\"employer\\", \\"location\\", \\"posted_text\\", \\"posted_date_est\\", \\"function_raw\\",\\n          \\"department\\", \\"ref_no\\", \\"salary_scale\\", \\"vacancies\\", \\"deadline\\", \\"employment_type\\", \\"salary_text\\",\\n          \\"description_raw\\"]\\nSUPPLY = [\\"institution\\", \\"ceremony\\", \\"award_level\\", \\"programme\\", \\"graduate_count\\",\\n          \\"count_basis\\", \\"rows_matched\\", \\"count_confidence\\", \\"field_group_provisional\\"]\\nFIELDS = PROVENANCE + DEMAND + SUPPLY\\n\\n\\ndef now_iso():\\n    return datetime.now(timezone.utc).replace(microsecond=0).isoformat()\\n\\n\\ndef sha(*parts):\\n    return hashlib.sha256(\\"|\\".join(str(p or \\"\\").strip().lower() for p in parts).encode()).hexdigest()\\n\\n\\ndef make_record(record_type, source, source_url, retrieved_at, method, id_parts, raw_for_hash, **fields):\\n    rec = {k: \\"\\" for k in FIELDS}\\n    rec.update(fields)\\n    rec.update({\\n        \\"record_type\\": record_type, \\"source\\": source, \\"source_url\\": source_url,\\n        \\"retrieved_at\\": retrieved_at, \\"retrieval_method\\": method,\\n        \\"pipeline_version\\": __version__,\\n        \\"record_id\\": f\\"{source}:{sha(*id_parts)[:16]}\\",\\n        \\"raw_hash\\": sha(raw_for_hash),\\n    })\\n    return rec\\n\\n\\n_REL = re.compile(r\\"(\\\\d+)\\\\s+(day|week|month|year)s?\\\\s+ago\\", re.I)\\n\\n\\ndef estimate_posted_date(text, retrieved_iso):\\n    \\"\\"\\"Convert \'Today\', \'Yesterday\', \'4 days ago\' to an ESTIMATED date (precision is coarse).\\"\\"\\"\\n    if not text:\\n        return \\"\\"\\n    base = datetime.fromisoformat(retrieved_iso).date()\\n    t = text.strip().lower()\\n    if t == \\"today\\":\\n        return base.isoformat()\\n    if t == \\"yesterday\\":\\n        return (base - timedelta(days=1)).isoformat()\\n    m = _REL.search(t)\\n    if m:\\n        n, unit = int(m.group(1)), m.group(2).lower()\\n        days = {\\"day\\": 1, \\"week\\": 7, \\"month\\": 30, \\"year\\": 365}[unit] * n\\n        return (base - timedelta(days=days)).isoformat()\\n    return \\"\\"\\n\\n\\ndef write_csv(records, path):\\n    with open(path, \\"w\\", newline=\\"\\", encoding=\\"utf-8\\") as fh:\\n        w = csv.DictWriter(fh, fieldnames=FIELDS, extrasaction=\\"ignore\\")\\n        w.writeheader()\\n        w.writerows(records)\\n\\n\\ndef write_json(records, path):\\n    with open(path, \\"w\\", encoding=\\"utf-8\\") as fh:\\n        json.dump(records, fh, indent=2, ensure_ascii=False)\\n", "src/skillsgap/quality.py": "\\"\\"\\"Data-quality report: counts by source, missingness, duplicates, parse failures, provenance completeness.\\"\\"\\"\\nfrom collections import Counter\\n\\nfrom .schema import DEMAND, PROVENANCE, SUPPLY\\n\\n\\ndef report(records, failures, client_stats=None):\\n    by_source = Counter(r[\\"source\\"] for r in records)\\n    out = {\\"total_records\\": len(records), \\"by_source\\": dict(by_source),\\n           \\"by_type\\": dict(Counter(r[\\"record_type\\"] for r in records))}\\n    miss = {}\\n    for rtype, fields in ((\\"demand\\", DEMAND), (\\"supply\\", SUPPLY)):\\n        subset = [r for r in records if r[\\"record_type\\"] == rtype]\\n        if not subset:\\n            continue\\n        miss[rtype] = {f: round(100 * sum(1 for r in subset if str(r.get(f, \\"\\")).strip() == \\"\\") / len(subset), 1)\\n                       for f in fields}\\n    out[\\"missing_pct\\"] = miss\\n    ids = Counter(r[\\"record_id\\"] for r in records)\\n    out[\\"duplicate_record_ids\\"] = sum(1 for v in ids.values() if v > 1)\\n    demand = [r for r in records if r[\\"record_type\\"] == \\"demand\\"]\\n    keys = Counter((r[\\"title\\"].lower(), r[\\"employer\\"].lower()) for r in demand)\\n    out[\\"demand_duplicate_title_employer\\"] = sum(v - 1 for v in keys.values() if v > 1)\\n    prov_missing = [r[\\"record_id\\"] for r in records if any(str(r.get(f, \\"\\")).strip() == \\"\\" for f in\\n                    (\\"record_id\\", \\"source\\", \\"source_url\\", \\"retrieved_at\\", \\"retrieval_method\\", \\"raw_hash\\"))]\\n    out[\\"provenance_incomplete\\"] = len(prov_missing)\\n    out[\\"no_stable_record_url\\"] = sum(1 for r in records if not r.get(\\"record_url\\"))\\n    out[\\"supply_count_confidence\\"] = dict(Counter(r.get(\\"count_confidence\\", \\"\\") for r in records\\n                                                  if r[\\"record_type\\"] == \\"supply\\"))\\n    out[\\"parse_failures\\"] = len(failures)\\n    out[\\"parse_failure_detail\\"] = failures[:20]\\n    if client_stats:\\n        out[\\"http\\"] = client_stats\\n    return out\\n", "tests/test_pipeline.py": "import json, subprocess, sys\\nfrom pathlib import Path\\nimport pytest\\nfrom skillsgap.demand import parse_brightermonday_listing, parse_district_advert\\nfrom skillsgap.schema import estimate_posted_date, FIELDS\\nfrom skillsgap.supply import classify_field, classify_level, parse_graduation_pdf\\nfrom skillsgap.quality import report\\nfrom skillsgap.http import PoliteClient, RobotsDisallowed\\nfrom skillsgap.config import load_config\\n\\nFX = Path(__file__).parent / \\"fixtures\\"\\nTS = \\"2026-10-21T14:00:00+00:00\\"\\n\\n\\ndef test_bm_parser_dedupes_and_flags_missing_employer():\\n    recs, fails = parse_brightermonday_listing((FX / \\"bm_listing.html\\").read_text(), \\"https://x.test/jobs\\", TS)\\n    assert [r[\\"title\\"] for r in recs] == [\\"Operations Manager\\", \\"Stock Controller\\", \\"Marketing Officer\\"]\\n    assert recs[0][\\"employer\\"] == \\"Cook Bright Initiative\\" and recs[0][\\"location\\"] == \\"Kampala\\"\\n    assert recs[1][\\"function_raw\\"] == \\"Supply Chain & Procurement\\"\\n    assert recs[1][\\"posted_date_est\\"] == \\"2026-10-07\\"\\n    assert any(f[\\"reason\\"] == \\"employer_not_found\\" for f in fails)\\n    assert all(r[\\"record_id\\"] and r[\\"raw_hash\\"] and r[\\"retrieved_at\\"] for r in recs)\\n\\n\\ndef test_district_parser_rows_and_deadline():\\n    recs, fails = parse_district_advert((FX / \\"district_advert.html\\").read_text(), \\"https://d.test/n/1\\", TS)\\n    assert len(recs) == 2 and recs[0][\\"deadline\\"] == \\"30th September 2026\\"\\n    assert recs[1][\\"vacancies\\"] == \\"6\\" and any(f[\\"reason\\"] == \\"row_without_title\\" for f in fails)\\n\\n\\ndef test_posted_date_estimates():\\n    assert estimate_posted_date(\\"Today\\", TS) == \\"2026-10-21\\"\\n    assert estimate_posted_date(\\"Yesterday\\", TS) == \\"2026-10-20\\"\\n    assert estimate_posted_date(\\"1 week ago\\", TS) == \\"2026-10-14\\"\\n    assert estimate_posted_date(\\"garbage\\", TS) == \\"\\"\\n\\n\\ndef test_graduation_pdf_counts_and_stores_no_names(tmp_path):\\n    sys.path.insert(0, str(Path(__file__).parent))\\n    from make_pdf_fixture import build\\n    p = tmp_path / \\"g.pdf\\"; build(str(p))\\n    meta = {\\"name\\": \\"TEST\\", \\"url\\": \\"https://t.test/g.pdf\\", \\"institution\\": \\"Test U\\", \\"ceremony\\": \\"1st\\"}\\n    recs, fails = parse_graduation_pdf(p.read_bytes(), meta, TS)\\n    got = {r[\\"programme\\"]: r[\\"graduate_count\\"] for r in recs}\\n    assert got[\\"Bachelor of Science in Computer Science\\"] == 5 and got[\\"Bachelor of Laws\\"] == 3\\n    assert any(\\"Diploma in Business Studies\\" in f[\\"reason\\"] for f in fails)\\n    blob = json.dumps(recs)\\n    assert \\"Testname\\" not in blob and \\"Surname\\" not in blob\\n\\n\\ndef test_classifiers():\\n    assert classify_level(\\"Master of Business Administration\\") == \\"Masters\\"\\n    assert classify_level(\\"Postgraduate Diploma in Finance\\") == \\"Postgraduate diploma\\"\\n    assert classify_field(\\"Bachelor of Science in Computer Science\\") == \\"STEM\\"\\n    assert classify_field(\\"Bachelor of Laws\\") == \\"NON_STEM\\"\\n    assert classify_field(\\"Bachelor of Medicine and Bachelor of Surgery\\") == \\"REVIEW_HEALTH\\"\\n    assert classify_field(\\"Master of Information Technology Management\\") == \\"STEM\\"\\n\\n\\ndef test_quality_report_provenance():\\n    recs, fails = parse_brightermonday_listing((FX / \\"bm_listing.html\\").read_text(), \\"https://x.test/jobs\\", TS)\\n    rep = report(recs, fails)\\n    assert rep[\\"provenance_incomplete\\"] == 0 and rep[\\"by_source\\"][\\"brightermonday\\"] == 3\\n\\n\\nclass FakeResp:\\n    def __init__(self, code, body=b\\"ok\\", headers=None):\\n        self.status_code, self.content, self.headers = code, body, headers or {}\\n        self.text = body.decode()\\n    def raise_for_status(self):\\n        import requests\\n        if self.status_code >= 400: raise requests.HTTPError(str(self.status_code))\\n\\nclass FakeSession:\\n    def __init__(self, seq): self.seq, self.calls, self.headers = list(seq), [], {}\\n    def get(self, url, timeout=None):\\n        self.calls.append(url)\\n        if url.endswith(\\"/robots.txt\\"): return FakeResp(200, b\\"User-agent: *\\\\nDisallow: /private\\\\n\\")\\n        return self.seq.pop(0)\\n\\n\\ndef _client(tmp_path, seq, sleeps):\\n    cfg = load_config(); cfg[\\"http\\"][\\"cache_dir\\"] = str(tmp_path / \\"c\\")\\n    return PoliteClient(cfg, \\"TestUA\\", tmp_path, session=FakeSession(seq), sleep=sleeps.append)\\n\\n\\ndef test_retry_backoff_then_success_and_cache(tmp_path):\\n    sleeps = []\\n    c = _client(tmp_path, [FakeResp(503), FakeResp(200, b\\"hello\\")], sleeps)\\n    body, meta = c.get(\\"https://h.test/a\\")\\n    assert body == b\\"hello\\" and c.stats[\\"retries\\"] == 1 and any(s >= 2 for s in sleeps)\\n    body2, meta2 = c.get(\\"https://h.test/a\\")\\n    assert meta2[\\"from_cache\\"] and c.stats[\\"cache_hits\\"] == 1 and c.stats[\\"requests\\"] == 2\\n\\n\\ndef test_robots_disallow_blocks(tmp_path):\\n    c = _client(tmp_path, [], [])\\n    with pytest.raises(RobotsDisallowed):\\n        c.get(\\"https://h.test/private/x\\")\\n\\n\\ndef test_rate_limit_spaces_requests(tmp_path):\\n    sleeps = []\\n    c = _client(tmp_path, [FakeResp(200, b\\"1\\"), FakeResp(200, b\\"2\\")], sleeps)\\n    c.get(\\"https://h.test/1\\"); c.get(\\"https://h.test/2\\")\\n    assert any(s > 0 for s in sleeps)\\n\\n\\ndef test_end_to_end_run_with_fake_client(tmp_path):\\n    \\"\\"\\"Whole pipeline (extract->transform->load) against fixtures served by a fake client.\\"\\"\\"\\n    import copy\\n    from skillsgap import pipeline\\n    cfg = copy.deepcopy(load_config())\\n    cfg[\\"sources\\"][\\"brightermonday\\"][\\"listing_url\\"] = \\"https://bm.test/jobs\\"\\n    cfg[\\"sources\\"][\\"district_adverts\\"][\\"urls\\"] = [\\"https://d.test/n/1\\"]\\n    cfg[\\"sources\\"][\\"graduation_lists\\"][\\"lists\\"] = []\\n    pages = {\\"https://bm.test/jobs\\": (FX / \\"bm_listing.html\\").read_bytes(),\\n             \\"https://d.test/n/1\\": (FX / \\"district_advert.html\\").read_bytes()}\\n\\n    class FakeClient:\\n        ua = \\"TestUA\\"; stats = {\\"requests\\": 0}\\n        def get(self, url):\\n            if url not in pages: return b\\"<html></html>\\", {\\"from_cache\\": False}\\n            return pages[url], {\\"from_cache\\": False}\\n\\n    recs, fails, rep = pipeline.run(cfg, tmp_path / \\"out\\", client=FakeClient())\\n    assert rep[\\"by_source\\"] == {\\"brightermonday\\": 3, \\"district_adverts\\": 2}\\n    assert rep[\\"provenance_incomplete\\"] == 0\\n    for f in (\\"dataset.csv\\", \\"dataset.json\\", \\"quality_report.json\\", \\"compliance_run_log.csv\\", \\"run_manifest.json\\"):\\n        assert (tmp_path / \\"out\\" / f).exists()\\n    # re-run is idempotent: identical record ids\\n    recs2, _, _ = pipeline.run(cfg, tmp_path / \\"out2\\", client=FakeClient())\\n    assert sorted(r[\\"record_id\\"] for r in recs) == sorted(r[\\"record_id\\"] for r in recs2)\\n\\n\\ndef test_district_text_rows_parsed_from_real_advert_layout():\\n    recs, fails = parse_district_advert((FX / \\"district_advert_text.html\\").read_text(), \\"https://d.test/n/61\\", TS)\\n    assert [r[\\"title\\"] for r in recs] == [\\"District Education Officer\\", \\"Education Assistant II\\",\\n                                          \\"Principal Internal Auditor\\", \\"Senior Accountant\\",\\n                                          \\"Assistant Law Enforcement Officer\\"]\\n    assert recs[1][\\"vacancies\\"] == \\"6\\" and recs[3][\\"ref_no\\"] == \\"LYDSC/4/4/2026\\"\\n    assert recs[0][\\"deadline\\"] == \\"30th September 2026\\" and not fails\\n\\n\\ndef test_highest_serial_beats_matched_rows_and_heading_cleanup():\\n    from skillsgap.supply import count_programmes, clean_heading\\n    lines = [\\"BACHELOR OF LAWS\\", \\"1 A B\\", \\"2 C D\\", \\"garbled line\\", \\"4 E F\\", \\"9 G H\\",\\n             \\"2025 Graduation Ceremony\\", \\"DIPLOMA IN BUSINESS STUDIES t\\", \\"1 X Y\\"]\\n    b, orphan = count_programmes(lines)\\n    # the stray \\"2025 ...\\" line is matched as a row but must NOT become the count (last valid serial = 9)\\n    assert b[0] == (\\"BACHELOR OF LAWS\\", 5, 9) and b[1][0] == \\"DIPLOMA IN BUSINESS STUDIES\\"\\n    assert clean_heading(\\"BACHELOR OF SCIENCE IN COMPUTER SCIENCE .\'qt(\'\\") == \\"BACHELOR OF SCIENCE IN COMPUTER SCIENCE\\"\\n\\n\\ndef test_bm_real_card_structure():\\n    recs, fails = parse_brightermonday_listing((FX / \\"bm_card_real.html\\").read_text(), \\"https://x.test/jobs\\", TS)\\n    r = recs[0]\\n    assert r[\\"title\\"] == \\"Sales & Marketing Executive\\" and r[\\"employer\\"] == \\"The Dove\'s Nest Hotel\\"\\n    assert r[\\"location\\"] == \\"Rest of Uganda (Gulu)\\" and r[\\"employment_type\\"] == \\"Full Time\\"\\n    assert r[\\"salary_text\\"] == \\"USh 500,000 - 1,000,000\\" and r[\\"function_raw\\"] == \\"Marketing & Communications\\"\\n    assert r[\\"record_url\\"].endswith(\\"sales-marketing-executive-7wezne\\") and not fails\\n\\n\\ndef test_bm_age_found_outside_card_and_not_mixed_between_jobs():\\n    recs, fails = parse_brightermonday_listing((FX / \\"bm_age_sibling.html\\").read_text(), \\"https://x.test/jobs\\", TS)\\n    got = {r[\\"title\\"]: (r[\\"employer\\"], r[\\"location\\"], r[\\"posted_text\\"], r[\\"posted_date_est\\"]) for r in recs}\\n    assert got[\\"Job A\\"] == (\\"Employer A\\", \\"Kampala\\", \\"2 weeks ago\\", \\"2026-10-07\\")\\n    assert got[\\"Job B\\"][2] == \\"5 days ago\\"\\n    assert got[\\"Job C\\"][2] == \\"\\"          # no age shown for this job: must stay empty, not borrow a neighbour\'s\\n\\n\\ndef test_serial_jump_and_confidence():\\n    from skillsgap.supply import count_programmes, count_confidence\\n    lines = [\\"MASTER OF PUBLIC HEALTH\\"] + [f\\"{n} A B\\" for n in (1, 2, 3, 40, 41)] + [\\"99999 x\\"]\\n    b, _ = count_programmes(lines)\\n    assert b[0][2] == 41                       # jump of 37 (a lost page) accepted, stray number ignored\\n    assert count_confidence(41, 41) == \\"high\\" and count_confidence(74, 18) == \\"low\\" and count_confidence(30, 22) == \\"medium\\"\\n"}')

for rel, text in FILES.items():
    p = Path(rel)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(text, encoding="utf-8")
    print("written", rel)
print("Done. Next: python -m pytest -q tests")
